// NetSuite write-back — PROPOSAL stage only.
//
// A posted journal entry does NOT go straight to NetSuite: writing into the
// system of record is gated on human approval. This node turns ledger.posted
// into a forge.write.propose envelope that the Forge write agent records as a
// pending proposal (forge.write.requested). Nothing reaches NetSuite until a
// reviewer publishes forge.write.decision{decision:'approve'}, at which point
// Forge executes it through its Vault-signed, idempotency-keyed ERP writer.
//
// This node intentionally performs NO ERP call. Removing the direct POST is
// what closes the approval-gate bypass (PRD FR4 / W1).
const evt = $json;
const e = evt.payload ?? evt;

const amount = (e.amount_minor ?? 0) / 100;
const diff_preview = `+ NetSuite journalEntry for ledger entry ${e.entry_id ?? '?'} `
  + `(${e.currency ?? ''} ${amount.toFixed(2)})`;

return {
  json: {
    subject: 'forge.write.propose',
    schema_version: 1,
    source: 'n8n:netsuite-sync',
    correlation_id: evt.correlation_id ?? null,
    payload: {
      tenant_id: e.tenant_id ?? 'tenant-acme',
      erp_platform: 'netsuite',
      operation: 'create',
      target_module: 'journalEntry',
      payload: e,
      requested_by: 'n8n:netsuite-sync',
      diff_preview,
    },
  },
};
